mapper.sql:
WHERE user_id = #{userId}

    AND approved_at >= CONCAT(#{startDate}, ' 00:00:00')


    AND approved_at <= CONCAT(#{endDate}, ' 23:59:59')


    AND payment_source_type = #{paymentSourceType}


    AND transaction_type = #{transactionType}


    AND card_id = #{cardId}

WHERE user_id = #{userId}
AND status != 'CANCELED'

    AND approved_at >= CONCAT(#{startDate}, ' 00:00:00')


    AND approved_at <= CONCAT(#{endDate}, ' 23:59:59')


    AND payment_source_type = #{paymentSourceType}


    AND card_id = #{cardId}

mapper.update:
UPDATE transactions
SET status = #{status},
    updated_at = NOW()
    , approved_at = #{approvedAt}
WHERE id = #{transactionId}

UPDATE transactions
SET status = 'CANCELED', cancelled_at = NOW()
WHERE id = #{transactionId}
